function isValidRummikubWord(word) {
    if (!word) return false;
    const w = word.toLowerCase();
    return WORD_CHINESE_MAP.hasOwnProperty(w) && WORD_CHINESE_MAP[w] !== '';
}

function getWordChineseMeaning(word) {
    if (!word) return '';
    const w = word.toLowerCase();
    return WORD_CHINESE_MAP[w] || '';
}

